[{"order":1,"type":"heading","text":"Advanced TypeScript: Mastering Function Utilities (Parameters, ReturnType, Awaited)"},{"order":2,"type":"paragraph","text":"TypeScript provides powerful built-in utility types that allow developers to extract and manipulate types directly from existing functions. Mastering 'Parameters', 'ReturnType', and 'Awaited' ensures your codebase remains DRY (Don't Repeat Yourself) and type-safe."},{"order":3,"type":"subheading","text":"1. Extracting Argument Types with Parameters<T>"},{"order":4,"type":"paragraph","text":"The 'Parameters<T>' utility type extracts the parameter types of a function type 'T' as a tuple. This is extremely useful when you need to type wrapper functions or event handlers without manually duplicating types."},{"order":5,"type":"code","text":"function createUser(name: string, age: number, isActive: boolean) {
  return { id: 1, name, age, isActive };
}

type CreateUserParams = Parameters<typeof createUser>;
// Evaluates to: [name: string, age: number, isActive: boolean]

const args: CreateUserParams = ['Alice', 30, true];
const user = createUser(...args);"},{"order":6,"type":"subheading","text":"2. Extracting Output Types with ReturnType<T>"},{"order":7,"type":"paragraph","text":"Conversely, 'ReturnType<T>' extracts the return type of a function. If a function's implementation changes in the future, any type relying on 'ReturnType' automatically updates, preventing cascading type mismatches."},{"order":8,"type":"code","text":"function fetchConfiguration() {
  return {
    theme: 'dark',
    retries: 3,
    timeout: 5000
  };
}

type ConfigType = ReturnType<typeof fetchConfiguration>;
// Evaluates to: { theme: string; retries: number; timeout: number; }

const currentConfig: ConfigType = {
  theme: 'light',
  retries: 5,
  timeout: 1000
};"},{"order":9,"type":"subheading","text":"3. Unwrapping Promises with Awaited<T>"},{"order":10,"type":"paragraph","text":"Introduced in TypeScript 4.5, 'Awaited<T>' models the operation of 'awaiting' synchronously or asynchronously, recursively unwrapping promises. This is particularly useful for extracting the resolved type of an asynchronous function."},{"order":11,"type":"code","text":"async function fetchUserData() {
  return {
    id: 42,
    username: 'developer_joe'
  };
}

// Step 1: Get the Promise return type
type UserPromise = ReturnType<typeof fetchUserData>;

// Step 2: Unwrap the Promise to get the actual data structure
type UserData = Awaited<UserPromise>;
// Evaluates to: { id: number; username: string; }

const userRecord: UserData = {
  id: 100,
  username: 'senior_dev'
};"},{"order":12,"type":"subheading","text":"Summary of Best Practices"},{"order":13,"type":"bullet_point","text":"Always combine these utilities with 'typeof' when targeting existing functions rather than explicit type signatures."},{"order":14,"type":"bullet_point","text":"Use 'Parameters' for higher-order functions and method decorators."},{"order":15,"type":"bullet_point","text":"Use 'ReturnType' and 'Awaited' together to cleanly consume third-party API client return types without relying on duplicated interfaces."}]
